<script setup>
import {ref,reactive,computed,watch} from 'vue'
import {useRoute} from 'vue-router'
import {api,errorText} from '../../services/api'
import {query,states,date,price,conflictText} from '../../services/property'
import Pager from './Pager.vue'
import PrivateImage from './PrivateImage.vue'
import ReportDetails from './ReportDetails.vue'
const route=useRoute(),section=computed(()=>route.path.split('/').pop()),busy=ref(false),acting=ref(false),error=ref(''),notice=ref(''),data=ref({items:[],page:0,totalPages:0,totalElements:0}),stats=ref({}),selected=ref(null),command=reactive({reason:'',status:'',assignedTo:''}),filters=reactive({status:'',role:'',keyword:'',entityType:'',actorId:'',action:''})
const title=computed(()=>({dashboard:'Tổng quan hệ thống',posts:'Kiểm duyệt tin đăng',users:'Quản lý tài khoản',reports:'Xử lý báo cáo','audit-logs':'Nhật ký hoạt động','ai-config':'Tính năng chưa khả dụng'})[section.value])
const labels={users:'Tài khoản',activeUsers:'Đang hoạt động',lockedUsers:'Đã khóa',properties:'Tin đăng',pendingProperties:'Chờ duyệt',publishedProperties:'Đang công khai',openReports:'Báo cáo mới',processingReports:'Đang xử lý',resolvedReports:'Đã giải quyết',rejectedReports:'Đã từ chối'}
let generation=0
async function load(page=0){const run=++generation;busy.value=true;error.value='';try{if(section.value==='ai-config')return;const paths={posts:'properties',users:'users',reports:'reports','audit-logs':'audit-logs'};if(section.value==='dashboard'){const result=await api('/admin/dashboard');if(run===generation)stats.value=result}else{const allowed=section.value==='posts'||section.value==='reports'?{status:filters.status}:section.value==='users'?{status:filters.status,role:filters.role,keyword:filters.keyword}:{entityType:filters.entityType,actorId:filters.actorId,action:filters.action};const result=await api('/admin/'+paths[section.value]+'?'+query({...allowed,page,size:20}));if(run===generation)data.value=result}}catch(e){if(run===generation)error.value=errorText(e)}finally{if(run===generation)busy.value=false}}
function select(item){selected.value=item;command.reason='';command.status=section.value==='users'?(item.status==='ACTIVE'?'LOCKED':'ACTIVE'):'';command.assignedTo='';notice.value=''}
async function act(action){if(acting.value||!command.reason.trim()){error.value='Nhập lý do / ghi chú trước khi thực hiện.';return}acting.value=true;error.value='';try{const item=selected.value;let path,body;if(section.value==='posts'){path='/admin/properties/'+item.property.id+'/moderation';body={action,expectedVersion:item.property.contentVersion,reason:command.reason}}else if(section.value==='users'){path='/admin/users/'+item.id+'/status';body={status:command.status,reason:command.reason}}else{path='/admin/reports/'+item.id+'/status';body={status:command.status,note:command.reason,assignedTo:command.assignedTo?Number(command.assignedTo):null}}await api(path,{method:section.value==='posts'?'POST':'PATCH',body});selected.value=null;notice.value='Đã cập nhật thành công.';await load(data.value.page)}catch(e){error.value=e.status===409?conflictText(e):errorText(e)}finally{acting.value=false}}
watch(()=>section.value,()=>{Object.assign(filters,{status:section.value==='posts'?'PENDING':'',role:'',keyword:'',entityType:'',actorId:'',action:''});selected.value=null;data.value={items:[],page:0,totalPages:0,totalElements:0};notice.value='';load()},{immediate:true})
</script>
<template><h1 style="margin-top:28px">{{title}}</h1><p v-if="busy" role="status">Đang tải dữ liệu…</p><p v-if="error" role="alert" class="sp-error">{{error}} <button :disabled="busy" @click="load(data.page)">Tải lại danh sách</button></p><p v-if="notice" role="status" class="sp-success">{{notice}}</p>
<div v-if="section==='dashboard'" class="sp-grid"><section v-for="(value,key) in stats" :key="key" class="sp-panel"><p class="sp-muted">{{labels[key]||key}}</p><strong style="font-size:34px">{{value}}</strong></section></div>
<p v-else-if="section==='ai-config'" class="sp-panel">Chưa có chức năng quản trị AI trong phiên bản này.</p>
<template v-else><form class="sp-panel sp-row" @submit.prevent="selected=null;load(0)"><template v-if="['users','reports','posts'].includes(section)"><label>Trạng thái <select v-model="filters.status"><option v-if="section!=='posts'" value="">Tất cả</option><option v-for="key in section==='users'?['ACTIVE','LOCKED']:section==='reports'?['OPEN','PROCESSING','RESOLVED','REJECTED']:['DRAFT','PENDING','PUBLISHED','REJECTED','HIDDEN','CLOSED','EXPIRED']" :key="key" :value="key">{{states[key]}}</option></select></label></template><template v-if="section==='users'"><input v-model="filters.keyword" placeholder="Tìm tên/email" maxlength="100" aria-label="Tìm tài khoản"><select v-model="filters.role" aria-label="Vai trò"><option value="">Mọi vai trò</option><option>BUYER</option><option>BROKER</option><option>ADMIN</option></select></template><template v-if="section==='audit-logs'"><select v-model="filters.entityType" aria-label="Đối tượng"><option value="">Mọi đối tượng</option><option>USER</option><option>PROPERTY</option><option>REPORT</option></select><input v-model="filters.actorId" type="number" min="1" placeholder="ID người thao tác" aria-label="ID người thao tác"><input v-model="filters.action" maxlength="100" placeholder="Hành động" aria-label="Hành động"></template><button class="sp-primary" :disabled="busy">Lọc</button></form>
<div v-if="!busy&&!error&&!data.items.length" class="sp-empty">Chưa có dữ liệu phù hợp.</div><div v-else class="sp-panel sp-table-wrap"><table><thead><tr><th>{{section==='users'?'Tài khoản':section==='posts'?'Tin đăng':section==='reports'?'Báo cáo':'Hành động'}}</th><th>Trạng thái / nội dung</th><th>Thời gian</th><th v-if="section!=='audit-logs'">Thao tác</th></tr></thead><tbody><tr v-for="item in data.items" :key="item.property?.id||item.id"><td>{{section==='users'?item.fullName:section==='posts'?item.property.title:section==='reports'?item.reasonCode:item.action}}<p class="sp-muted">{{section==='users'?item.email:section==='posts'?price(item.property):item.id}}</p></td><td v-if="section==='audit-logs'"><p>{{item.entityType}} · {{item.entityId||item.entityNumericId}} · người thao tác {{item.actorId??'Hệ thống'}}</p><p>{{item.oldValues?.status||'—'}} → {{item.newValues?.status||'—'}}</p></td><td v-else><span class="sp-tag">{{states[item.property?.status||item.status]}}</span><p v-if="section==='users'" class="sp-muted">{{item.role}} · {{item.lockReason}}</p></td><td>{{date(item.property?.createdAt||item.createdAt)}}</td><td v-if="section!=='audit-logs'"><button :disabled="acting" @click="select(item)">Xem / xử lý</button></td></tr></tbody></table></div><Pager v-bind="data" :busy="busy" @change="selected=null;load($event)"/>
<section v-if="selected" class="sp-panel"><h2>Xử lý {{section==='users'?selected.fullName:section==='posts'?selected.property.title:'báo cáo'}}</h2><template v-if="section==='posts'"><p class="sp-pre">{{selected.property.description}}</p><p>{{selected.property.address}} · {{selected.property.latitude}}, {{selected.property.longitude}}</p><p>{{selected.contactName}} · {{selected.contactPhone}} · {{selected.contactEmail}}</p><div class="sp-grid"><PrivateImage v-for="image in selected.property.images" :key="image.id" class="sp-cover" :src="image.url" alt="Ảnh chờ kiểm duyệt"/></div></template><ReportDetails v-if="section==='reports'" :report="selected" admin/>
<div v-if="section==='posts'||section==='users'||!['RESOLVED','REJECTED'].includes(selected.status)"><label class="sp-label">Lý do / ghi chú<textarea v-model="command.reason" maxlength="4000" required></textarea></label><div v-if="section==='reports'" class="sp-row" style="margin:16px 0"><select v-model="command.status" aria-label="Trạng thái mới"><option value="">Chọn trạng thái mới</option><option v-if="selected.status==='OPEN'" value="PROCESSING">Đang xử lý</option><option value="RESOLVED">Đã giải quyết</option><option value="REJECTED">Từ chối</option></select><input v-model="command.assignedTo" type="number" min="1" placeholder="ID quản trị viên phụ trách (tùy chọn)" aria-label="ID người phụ trách"></div><div class="sp-actions"><template v-if="section==='posts'"><button v-if="selected.property.status==='PENDING'" class="sp-primary" :disabled="acting" @click="act('APPROVE')">Duyệt đăng</button><button v-if="selected.property.status==='PENDING'" :disabled="acting" @click="act('REJECT')">Từ chối</button><button v-if="selected.property.status==='PUBLISHED'" :disabled="acting" @click="act('HIDE')">Ẩn tin</button><button v-if="selected.property.status==='HIDDEN'" :disabled="acting" @click="act('RESTORE')">Đưa về chờ duyệt</button></template><button v-else class="sp-primary" :disabled="acting||(section==='reports'&&!command.status)" @click="act()">{{section==='users'?(command.status==='LOCKED'?'Khóa tài khoản':'Mở khóa tài khoản'):'Lưu kết quả xử lý'}}</button><button :disabled="acting" @click="selected=null">Đóng</button></div></div>
</section></template></template>